import{_ as a,o,c as t,a2 as r}from"./chunks/framework.CHeM0PsO.js";const p=JSON.parse('{"title":"Guard Name Local Storage Design","description":"","frontmatter":{},"headers":[],"relativePath":"superpowers/specs/2026-05-22-guard-name-local-storage-design.md","filePath":"superpowers/specs/2026-05-22-guard-name-local-storage-design.md"}'),d={name:"superpowers/specs/2026-05-22-guard-name-local-storage-design.md"};function s(n,e,l,c,i,u){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="guard-name-local-storage-design" tabindex="-1">Guard Name Local Storage Design <a class="header-anchor" href="#guard-name-local-storage-design" aria-label="Permalink to &quot;Guard Name Local Storage Design&quot;">​</a></h1><h2 id="goal" tabindex="-1">Goal <a class="header-anchor" href="#goal" aria-label="Permalink to &quot;Goal&quot;">​</a></h2><p>When a guard successfully authenticates from <code>/guard</code>, save the authenticated guard name in browser local storage. When the guard screen is shown again with a fresh or reset form, prefill the guard name field with the saved name.</p><h2 id="current-flow" tabindex="-1">Current Flow <a class="header-anchor" href="#current-flow" aria-label="Permalink to &quot;Current Flow&quot;">​</a></h2><p><code>src/app/guard/page.tsx</code> renders <code>Phase1App</code> with <code>mode=&quot;guard&quot;</code>. The guard form lives in <code>src/app/phase1-app.tsx</code> and submits through <code>handleGuardAuth</code>, which posts <code>name</code> and <code>phone</code> to <code>/api/guard/auth</code>. On success it stores the returned <code>GuardSession</code> in React state and shows guard action buttons. On failure it clears the guard session and shows an alert.</p><h2 id="proposed-approach" tabindex="-1">Proposed Approach <a class="header-anchor" href="#proposed-approach" aria-label="Permalink to &quot;Proposed Approach&quot;">​</a></h2><p>Use a small local storage helper around one storage key, <code>ollbareun.guard.name</code>. Read the value on client mount and store it in <code>savedGuardName</code>. Render the guard name input as an uncontrolled field with <code>defaultValue={savedGuardName}</code> so it matches the existing <code>FormData</code> submit pattern. On successful authentication, write <code>session.employee.name</code> to local storage and update <code>savedGuardName</code> to the same value.</p><p>Authentication failures do not update local storage. This prevents failed attempts, retired employees, or typoed names from replacing the last verified guard name.</p><h2 id="components-and-data-flow" tabindex="-1">Components And Data Flow <a class="header-anchor" href="#components-and-data-flow" aria-label="Permalink to &quot;Components And Data Flow&quot;">​</a></h2><ul><li><code>Phase1App</code> owns a new <code>savedGuardName</code> string state.</li><li>Initial client effect reads <code>window.localStorage.getItem(&quot;ollbareun.guard.name&quot;)</code>.</li><li><code>handleGuardAuth</code> posts the submitted form values as it does today.</li><li>On successful response, <code>handleGuardAuth</code> persists <code>session.employee.name</code>.</li><li>The guard name input receives <code>defaultValue={savedGuardName}</code>.</li></ul><h2 id="error-handling" tabindex="-1">Error Handling <a class="header-anchor" href="#error-handling" aria-label="Permalink to &quot;Error Handling&quot;">​</a></h2><p>Local storage access is guarded by <code>typeof window !== &quot;undefined&quot;</code> and <code>try/catch</code>. If local storage is unavailable, blocked, or throws, the app keeps working with an empty default value. API authentication errors continue through the current alert and error message path.</p><h2 id="testing" tabindex="-1">Testing <a class="header-anchor" href="#testing" aria-label="Permalink to &quot;Testing&quot;">​</a></h2><p>Add a focused React test in <code>src/app/phase1-app.test.tsx</code> that:</p><ol><li>Clears local storage.</li><li>Authenticates successfully as <code>홍길동</code>.</li><li>Verifies <code>localStorage[&quot;ollbareun.guard.name&quot;]</code> is <code>홍길동</code>.</li><li>Unmounts and renders the guard screen again.</li><li>Verifies the <code>경비원 이름</code> input defaults to <code>홍길동</code>.</li></ol><p>The existing retired-employee test continues to prove failed authentication does not log the guard in.</p>',16)])])}const g=a(d,[["render",s]]);export{p as __pageData,g as default};
